// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, address actor1, address actor2) public {
        vm.assume(t1 > 0);
        vm.assume(actor1 != address(c) && actor2 != address(c));
        vm.deal(actor1, 10 ether);
        vm.deal(actor2, 10 ether);

        // first call succeeds and sets pastBlockTime = t1
        vm.warp(t1);
        vm.prank(actor1);
        c.fallback{value: 10 ether}();
        assertEq(c.pastBlockTime(), t1);

        // second call in the SAME block must revert in the reference
        vm.prank(actor2);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // Rule: a repeat call within the same timestamp is always rejected
        // (and pastBlockTime stays t1). The mutant accepts it.
        assertTrue(!ok && c.pastBlockTime() == t1);
    }
}

