pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 bn, address actor, uint256 wait) public {
        vm.assume(actor != address(c) && actor != address(this));
        // choose any block number divisible by 15 (payout block), keep domain wide
        bn = bound(bn, 15, type(uint248).max / 15 * 15);
        bn = bn - (bn % 15);
        assertTrue(bn % 15 == 0);
        uint256 ts = block.timestamp + 1 + (wait % 1_000_000);
        vm.deal(actor, 10 ether);
        vm.roll(bn);
        vm.warp(ts);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // General rule: on a block where block.number % 15 == 0, the contract
        // pays out everything, so its balance must be zero afterwards.
        assertTrue(address(c).balance == 0);
    }
}

