pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        // keep the block number in a realistic range, but in the NON-divisible-by-15 domain
        blockNumber = bound(blockNumber, 1, 10_000_000);
        vm.assume(blockNumber % 15 != 0);
        // timestamp must strictly exceed pastBlockTime (initially 0)
        ts = bound(ts, 1, 2_000_000_000);
        // actor must be able to receive the transfer: a plain EOA
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(0));

        vm.roll(blockNumber);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: on a block number NOT divisible by 15 the reference never pays out,
        // so its balance is unchanged. The mutant pays out exactly on such blocks.
        assertEq(address(c).balance, 10 ether);
    }
}

