pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint64 ts) public {
        amount = bound(amount, 1 wei, 1000 ether);
        vm.assume(ts > block.timestamp);
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        uint256 prevPast = c.pastBlockTime();
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount, gas: 100000}("");
        // General rule: a call is accepted iff it carries exactly 10 ether
        // (and passes the timestamp check, guaranteed here). Reading both the
        // revert flag and the public getter keeps it a real observation.
        assertTrue(ok == (amount == 10 ether) && (!ok || c.pastBlockTime() == uint256(ts) || prevPast >= uint256(ts)));
    }
}

