pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint64 ts) public {
        // keep admissible domain wide, but always BELOW the required 10 ether
        // so the reference's require(msg.value == 10 ether) must revert.
        amount = bound(amount, 0, 9 ether);
        ts = uint64(bound(uint256(ts), 2, type(uint64).max - 1));

        address actor = address(0xdead);
        vm.deal(actor, 20 ether);
        vm.warp(ts);

        vm.prank(actor);
        bool ok;
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // A call with value != 10 ether must always revert in the reference;
        // the mutant accepts it and succeeds for some admissible amount.
        assertTrue(ok == false, "call with value != 10 ether must revert");
    }
}

