pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t0, uint256 delta, address actor) public {
        vm.assume(t0 > 0);
        vm.assume(actor != address(0));
        delta = bound(delta, 0, 1e9);

        vm.warp(t0);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        vm.warp(t0 + delta);
        vm.deal(actor, 10 ether);
        bool ok2;
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule: a second successful call implies the timestamp strictly
        // advanced past the first call's timestamp (delta > 0). In the reference
        // C the second call in the same block always reverts; in the mutant it
        // succeeds even when delta == 0.
        assertTrue(!ok2 || delta > 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 n, uint256 ts, address actor) public {
        // wide admissible domain: any payout block (multiple of 15, nonzero), any nonzero timestamp, any actor
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        n = bound(n, 1, type(uint128).max);
        ts = bound(ts, 1, type(uint64).max);
        uint256 payoutBlock = n * 15;

        // call 1: block divisible by 15 -> succeeds and drains the whole balance to the caller
        vm.warp(ts);
        vm.roll(payoutBlock);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // call 2: same timestamp, next block (not divisible by 15) -> must be rejected by the timestamp check
        vm.roll(payoutBlock + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // the balance drained in call 1 is never re-funded: the second call must have reverted
        assertTrue(address(c).balance == 0);
    }
}

