pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IC {
    function pastBlockTime() external view returns (uint256);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockSeed) public {
        // Put ourselves on a payout block (block.number % 15 == 0) so the
        // fallback's payout branch fires; keep the domain wide via the seed.
        uint256 b = bound(blockSeed, 1, 1000);
        vm.roll(b * 15);

        // Adversarial re-entrant depositor: on receiving the payout it
        // immediately deposits 10 ether back into c (re-entry during the
        // outer transfer).
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        uint256 preBalance = address(c).balance; // 10 ether from setUp

        vm.deal(address(attacker), 10 ether);
        // Top-level deposit of 10 ether into c via fallback.
        attacker.attack();

        // GENERAL RULE: a successful top-level 10-ether deposit leaves the
        // contract holding exactly preBalance + 10 ether. In the reference,
        // pastBlockTime is already updated when the payout fires, so the
        // re-entrant inner deposit reverts and only the outer deposit lands.
        // In the mutant, pastBlockTime is stale during the payout, so the
        // re-entrant deposit succeeds and its own payout drains c to 0.
        assertTrue(address(c).balance == preBalance + 10 ether);
    }
}

contract ReentrantAttacker {
    address target;
    bool reentered;

    constructor(address t) { target = t; }

    function attack() external payable {
        (bool ok, ) = target.call{value: 10 ether}("");
        require(ok);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.call{value: 10 ether}("");
        }
    }
}
